nextflow_process {

    name "Test Process KRAKEN2_BUILD"
    script "../main.nf"
    process "KRAKEN2_BUILD"
    config "./nextflow.config"
    tag "kraken2"
    tag "kraken2/build"
    tag "kraken2/add"
    tag "gunzip"
    tag "modules"
    tag "modules_nfcore"

    setup {

        run("GUNZIP") {
            script "modules/nf-core/gunzip/main.nf"
            process {
                """
                input[0] = Channel.of([
                    [],
                    file(
                        params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot.accession2taxid.gz",
                        checkIfExists: true
                    )
                ])
                """
            }
        }

    }

    test("sarscov2 protein_db") {

        setup {
            run("KRAKEN2_ADD") {
                script "modules/nf-core/kraken2/add/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                            [
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/proteome.fasta", checkIfExists: true)
                            ]
                        ]
                    input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_names.dmp", checkIfExists: true)
                    input[2] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_nodes.dmp", checkIfExists: true)
                    input[3] = GUNZIP.out.gunzip.map{ it[1] }
                    input[4] = []
                    """
                }
            }
        }

        when {
            process {
                """
                ch_seqid2taxid = KRAKEN2_ADD.out.seqid2taxid_map.ifEmpty([[:],[]])

                input[0] = KRAKEN2_ADD.out.library_added_files
                input[1] = ch_seqid2taxid
                input[2] = KRAKEN2_ADD.out.taxonomy_files
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.db.get(0).get(1) ==~ ".*/kraken2-database" },
                { assert snapshot (
                        path("${process.out.db[0][1]}/hash.k2d"),
                        path("${process.out.db[0][1]}/taxo.k2d"),
                        file("${process.out.db[0][1]}/opts.k2d").name,
                        file("${process.out.db[0][1]}/unmapped.txt").name
                    ).match()
                }
            )
        }

    }

    test("sarscov2 protein_db - customs seqid2taxid") {

        setup {
            run("KRAKEN2_ADD", alias: "KRAKEN2_ADD_SEQID2TAXID") {
                script "modules/nf-core/kraken2/add/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                            [
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/proteome.fasta", checkIfExists: true)
                            ]
                        ]
                    input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_names.dmp", checkIfExists: true)
                    input[2] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_nodes.dmp", checkIfExists: true)
                    input[3] = GUNZIP.out.gunzip.map{ it[1] }
                    input[4] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_seqid2taxid.map", checkIfExists: true)
                    """
                }
            }
        }

        when {
            process {
                """
                ch_seqid2taxid = KRAKEN2_ADD_SEQID2TAXID.out.seqid2taxid_map.ifEmpty([[:],[]])

                input[0] = KRAKEN2_ADD_SEQID2TAXID.out.library_added_files
                input[1] = ch_seqid2taxid
                input[2] = KRAKEN2_ADD_SEQID2TAXID.out.taxonomy_files
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.db.get(0).get(1) ==~ ".*/kraken2-database" },
                { assert snapshot (
                        path("${process.out.db[0][1]}/hash.k2d"),
                        path("${process.out.db[0][1]}/taxo.k2d"),
                        file("${process.out.db[0][1]}/opts.k2d").name,
                        file("${process.out.db[0][1]}/unmapped.txt").name
                    ).match()
                }
            )
        }

    }

    test("sarscov2 protein_db stub") {

        options "-stub"

        setup {
            run("KRAKEN2_ADD", alias: "KRAKEN2_ADD_STUB") {
                script "modules/nf-core/kraken2/add/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                            [
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/proteome.fasta", checkIfExists: true)
                            ]
                        ]
                    input[1] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_names.dmp", checkIfExists: true)
                    input[2] = file(params.modules_testdata_base_path + "genomics/sarscov2/metagenome/prot_nodes.dmp", checkIfExists: true)
                    input[3] = GUNZIP.out.gunzip.map{ it[1] }
                    input[4] = []
                    """
                }
            }
        }

        when {
            process {
                """
                ch_seqid2taxid = KRAKEN2_ADD_STUB.out.seqid2taxid_map.ifEmpty([[:],[]])

                input[0] = KRAKEN2_ADD_STUB.out.library_added_files
                input[1] = ch_seqid2taxid
                input[2] = KRAKEN2_ADD_STUB.out.taxonomy_files
                input[3] = true
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot (process.out).match()
                }
            )
        }

    }

}

